import 'dart:async';
import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';

/// Golden comparison that tolerates rendering noise and fails on real change.
///
/// A Flutter upgrade, a font-hinting change or a different anti-aliasing
/// path moves a small fraction of pixels in every image without changing
/// what a user sees. Exact comparison turned each of those into dozens of
/// failures that had to be regenerated by hand, which trains everyone to
/// regenerate without looking. Here a golden fails only when more than
/// [goldenTolerance] of its pixels differ: a moved, resized, added or
/// removed region of the screen.
///
/// Goldens are therefore the coarse visual alarm. What a user can *do* is
/// protected separately and exactly, by the behavioural must-have feature
/// contract and the control inventory in `test/contract/`.
///
/// Set `GOLDEN_TOLERANCE` (a fraction, e.g. `0` for exact) to override.
const double defaultGoldenTolerance = 0.01;

double get goldenTolerance =>
    double.tryParse(Platform.environment['GOLDEN_TOLERANCE'] ?? '') ??
    defaultGoldenTolerance;

Future<void> testExecutable(FutureOr<void> Function() testMain) async {
  final current = goldenFileComparator;
  if (current is LocalFileComparator) {
    goldenFileComparator = TolerantGoldenFileComparator(
      // LocalFileComparator resolves goldens beside the test file.
      Uri.parse('${current.basedir}placeholder_test.dart'),
      tolerance: goldenTolerance,
    );
  }
  await testMain();
}

final class TolerantGoldenFileComparator extends LocalFileComparator {
  TolerantGoldenFileComparator(super.testFile, {required this.tolerance});

  /// The largest fraction of differing pixels that still passes.
  final double tolerance;

  @override
  Future<bool> compare(Uint8List imageBytes, Uri golden) async {
    final result = await GoldenFileComparator.compareLists(
      imageBytes,
      await getGoldenBytes(golden),
    );
    if (result.passed) {
      result.dispose();
      return true;
    }
    // A size change is never noise.
    final sizeChanged = result.diffPercent >= 1 || result.diffs == null;
    if (!sizeChanged && result.diffPercent <= tolerance) {
      debugPrint(
        'Golden ${golden.pathSegments.last}: '
        '${(result.diffPercent * 100).toStringAsFixed(3)}% of pixels differ, '
        'within the ${(tolerance * 100).toStringAsFixed(1)}% tolerance.',
      );
      result.dispose();
      return true;
    }
    final error = await generateFailureOutput(result, golden, basedir);
    result.dispose();
    throw FlutterError(error);
  }
}
